import type { Context } from 'hono';
// DB/config bindings are generated by `npm run types -w @street/api`.
export type Bindings = CloudflareBindings & { BOT_TOKEN?: string; WEBHOOK_SECRET?: string };
export type AppEnv = { Bindings: Bindings; Variables: { userId: string } };
export type Ctx = Context<AppEnv>;
export type RunRow = {
 id:string; user_id:string; seed:number; gang_id_at_start:string|null; membership_id:string|null;
 season_id:number; started_at:number; ended_at:number|null; status:string; wave:number;
 duration_seconds:number; kills:number; earned:number; run_level:number; verification_state:string;
 seq:number; distance:number; last_progress_at:number; settlement_id:string|null; gang_xp:number; is_new_record:number;
};
export type RoundRow = {
 id:string; user_id:string; game_type:'roulette'|'crash'|'blackjack'; stake:number; status:string;
 state:string; request_hash:string; started_at:number; expires_at:number; finished_at:number|null;
 payout:number; version:number; settlement_id:string|null;
};
